#include <iostream>
#include <algorithm>
#include <string>
using namespace std;

using i128 = __int128_t;

void printInt(i128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }
    string s;
    while (value > 0) {
        s.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    long long nn, mm, kk, xx, yy;
    cin >> nn >> mm >> kk >> xx >> yy;

    i128 n = nn, m = mm, k = kk, x = xx, y = yy;
    i128 maximum, minimum, sergei;

    if (n == 1) {
        i128 full = k / m;
        i128 remainder = k % m;

        minimum = full;
        maximum = full + (remainder > 0);
        sergei = full + (y <= remainder);
    } else {
        i128 cycle = 2 * (n - 1) * m;
        i128 full = k / cycle;
        i128 remainder = k % cycle;

        i128 endpointMax = full + (remainder > 0);
        i128 endpointMin = full + (remainder >= n * m);

        maximum = endpointMax;
        minimum = endpointMin;

        if (n > 2) {
            i128 internalMaxExtra = 0;
            if (remainder > m)
                internalMaxExtra = 1;
            if (remainder > n * m)
                internalMaxExtra = 2;

            i128 internalMinExtra =
                (remainder >= (n - 1) * m ? 1 : 0);

            maximum = max(maximum, 2 * full + internalMaxExtra);
            minimum = min(minimum, 2 * full + internalMinExtra);
        }

        if (x == 1 || x == n) {
            sergei = full;
        } else {
            sergei = 2 * full;
        }

        i128 firstPosition = (x - 1) * m + y;
        if (firstPosition <= remainder)
            ++sergei;

        if (x > 1 && x < n) {
            i128 secondPosition = n * m + (n - 1 - x) * m + y;
            if (secondPosition <= remainder)
                ++sergei;
        }
    }

    printInt(maximum);
    cout << ' ';
    printInt(minimum);
    cout << ' ';
    printInt(sergei);

    return 0;
}

