#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k, x, y;
    cin >> n >> m >> k >> x >> y;

    vector<vector<long long>> visits(n, vector<long long>(m, 0));

    if (n == 1) {
        long long rounds = k / m;
        long long remainder = k % m;

        for (long long col = 0; col < m; ++col) {
            visits[0][col] = rounds + (col < remainder);
        }
    } else {
        long long cycle = (2 * n - 2) * m;
        long long rounds = k / cycle;
        long long remainder = k % cycle;

        for (long long row = 0; row < n; ++row) {
            long long base = (row == 0 || row == n - 1) ? rounds : 2 * rounds;
            for (long long col = 0; col < m; ++col) {
                visits[row][col] = base;
            }
        }

        for (long long row = 0; row < n && remainder > 0; ++row) {
            for (long long col = 0; col < m && remainder > 0; ++col) {
                ++visits[row][col];
                --remainder;
            }
        }

        for (long long row = n - 2; row >= 1 && remainder > 0; --row) {
            for (long long col = 0; col < m && remainder > 0; ++col) {
                ++visits[row][col];
                --remainder;
            }
        }
    }

    long long maximum = 0;
    long long minimum = LLONG_MAX;

    for (const auto& row : visits) {
        for (long long value : row) {
            maximum = max(maximum, value);
            minimum = min(minimum, value);
        }
    }

    cout << maximum << ' ' << minimum << ' ' << visits[x - 1][y - 1];

    return 0;
}

