#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

using namespace std;

using int64 = long long;
using i128 = __int128_t;

void printInt128(i128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }

    if (value < 0) {
        cout << '-';
        value = -value;
    }

    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }

    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 nInput, mInput, kInput, xInput, yInput;
    cin >> nInput >> mInput >> kInput >> xInput >> yInput;

    i128 n = nInput;
    i128 m = mInput;
    i128 k = kInput;
    i128 x = xInput;
    i128 y = yInput;

    if (n == 1) {
        i128 minimum = k / m;
        i128 remainder = k % m;
        i128 maximum = minimum + (remainder > 0 ? 1 : 0);
        i128 target = minimum + (y <= remainder ? 1 : 0);

        printInt128(maximum);
        cout << ' ';
        printInt128(minimum);
        cout << ' ';
        printInt128(target);
        return 0;
    }

    i128 rowPeriod = 2 * n - 2;
    i128 periodSize = rowPeriod * m;
    i128 fullPeriods = k / periodSize;
    i128 remainder = k % periodSize;
    i128 fullRows = remainder / m;
    i128 partialColumns = remainder % m;

    auto completedCount = [&](i128 row) {
        i128 count = (row == 1 || row == n) ? fullPeriods : 2 * fullPeriods;

        if (fullRows >= row)
            ++count;

        if (row > 1 && row < n && fullRows >= 2 * n - row)
            ++count;

        return count;
    };

    i128 partialRow = -1;
    if (partialColumns > 0) {
        if (fullRows < n)
            partialRow = fullRows + 1;
        else
            partialRow = 2 * n - 1 - fullRows;
    }

    vector<i128> candidates;

    auto addCandidate = [&](i128 row) {
        if (row >= 1 && row <= n)
            candidates.push_back(row);
    };

    addCandidate(1);
    addCandidate(n);
    addCandidate(2);
    addCandidate(n - 1);
    addCandidate(fullRows);
    addCandidate(fullRows + 1);
    addCandidate(2 * n - fullRows);
    addCandidate(2 * n - fullRows - 1);
    addCandidate(partialRow);

    i128 maximum = -1;
    i128 minimum = k + 1;

    for (i128 row : candidates) {
        i128 count = completedCount(row);
        minimum = min(minimum, count);
        maximum = max(maximum, count);

        if (row == partialRow)
            maximum = max(maximum, count + 1);
    }

    i128 target = completedCount(x);
    if (x == partialRow && y <= partialColumns)
        ++target;

    printInt128(maximum);
    cout << ' ';
    printInt128(minimum);
    cout << ' ';
    printInt128(target);

    return 0;
}

